use serde_json::{json,Value};
use std::{fs,io::{Read,Write},net::TcpListener,os::{fd::{FromRawFd,AsRawFd},unix::fs::PermissionsExt},process::{Command,Stdio},sync::{Arc,Mutex,atomic::{AtomicBool,Ordering},mpsc},thread,time::{Duration,Instant}};
fn wait(mut check:impl FnMut()->bool){let until=Instant::now()+Duration::from_secs(8);while !check(){assert!(Instant::now()<until,"terminal fixture timed out");thread::sleep(Duration::from_millis(10));}}
#[test]
fn native_terminal_uses_server_pty_for_output_input_resize_and_detach(){
 let root=std::env::temp_dir().join(format!("ot3-terminal-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let token=root.join("token");fs::write(&token,"synthetic-terminal-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Remote fixture","base_url":format!("http://{}",listener.local_addr().unwrap()),"token_file":token,"write_token_file":token}]}).to_string()).unwrap();
 let stop=Arc::new(AtomicBool::new(false));let requests=Arc::new(Mutex::new(Vec::<Value>::new()));let received=Arc::new(Mutex::new(String::new()));let (done_tx,done_rx)=mpsc::channel();let done_rx=Arc::new(Mutex::new(done_rx));let server_stop=stop.clone();let server_requests=requests.clone();let server_received=received.clone();let peers=Arc::new(Mutex::new(vec![]));let workers=peers.clone();
 let server=thread::spawn(move||{while !server_stop.load(Ordering::Relaxed){if let Ok((mut s,_))=listener.accept(){let requests=server_requests.clone();let received=server_received.clone();let done=done_rx.clone();let child=thread::spawn(move||{
  s.set_read_timeout(Some(Duration::from_secs(8))).unwrap();let mut peek=[0;2048];let n=s.peek(&mut peek).unwrap();if String::from_utf8_lossy(&peek[..n]).starts_with("GET /ws"){
   let mut ws=tungstenite::accept(s).unwrap();let req:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();requests.lock().unwrap().push(req.clone());
   match req["tag"].as_str().unwrap(){
    "terminal.attach"=>{assert_eq!(req["payload"]["threadId"],"one");assert!(req["payload"]["terminalId"]=="term-1"||req["payload"]["terminalId"].as_str().unwrap().starts_with("term-ot3-"));assert_eq!(req["payload"]["cwd"],"/remote/work tree");assert_eq!(req["payload"]["providerInstanceId"],"provider");let chunk=json!({"_tag":"Chunk","requestId":"1","values":[{"type":"snapshot","snapshot":{"history":"HISTORY\r\n","sequence":4,"status":"running"}},{"type":"output","data":"SHOULD_NOT_REPEAT","sequence":4},{"type":"output","data":"LIVE_OUTPUT\r\n","sequence":5}]});ws.send(tungstenite::Message::Text(chunk.to_string().into())).unwrap();let ack:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();assert_eq!(ack["_tag"],"Ack");if done.lock().unwrap().recv_timeout(Duration::from_secs(8)).unwrap(){ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":[{"type":"exited","sequence":6,"exitCode":0}]}).to_string().into())).unwrap();let _=ws.read();}let _=ws.read();},
    "terminal.write"|"terminal.resize"=>{if req["tag"]=="terminal.write"{received.lock().unwrap().push_str(req["payload"]["data"].as_str().unwrap())}ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":{}}}).to_string().into())).unwrap();},
    _=>panic!("unexpected terminal RPC")
   }
  }else{let mut req=[0;8192];let n=s.read(&mut req).unwrap();assert!(String::from_utf8_lossy(&req[..n]).starts_with("GET /api/orchestration/shell"));let body=json!({"threads":[{"id":"one","projectId":"p","worktreePath":"/remote/work tree","modelSelection":{"instanceId":"provider"}}],"projects":[{"id":"p","workspaceRoot":"/remote/root"}]}).to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();}
 });workers.lock().unwrap().push(child);}else{thread::sleep(Duration::from_millis(5));}}});
 let(mut master,mut slave)=(0,0);let size=libc::winsize{ws_row:24,ws_col:80,ws_xpixel:0,ws_ypixel:0};assert_eq!(unsafe{libc::openpty(&mut master,&mut slave,std::ptr::null_mut(),std::ptr::null(),&size)},0);let mut master=unsafe{fs::File::from_raw_fd(master)};let slave=unsafe{fs::File::from_raw_fd(slave)};
 let mut original:libc::termios=unsafe{std::mem::zeroed()};assert_eq!(unsafe{libc::tcgetattr(slave.as_raw_fd(),&mut original)},0);
 let mut child=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).args(["terminal","fixture","one"]).env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",&config).stdin(Stdio::from(slave.try_clone().unwrap())).stdout(Stdio::from(slave.try_clone().unwrap())).stderr(Stdio::from(slave.try_clone().unwrap())).spawn().unwrap();
 unsafe{libc::fcntl(master.as_raw_fd(),libc::F_SETFL,libc::O_NONBLOCK)};let mut output=String::new();wait(||{let mut buf=[0;8192];if let Ok(n)=master.read(&mut buf){output.push_str(&String::from_utf8_lossy(&buf[..n]))}output.contains("LIVE_OUTPUT")});assert!(output.contains("HISTORY"));assert!(!output.contains("SHOULD_NOT_REPEAT"));
 master.write_all(b"h\xc3").unwrap();thread::sleep(Duration::from_millis(30));master.write_all(b"\xa9llo\x03").unwrap();wait(||received.lock().unwrap().as_str()=="héllo\x03");
 let new_size=libc::winsize{ws_row:40,ws_col:120,ws_xpixel:0,ws_ypixel:0};unsafe{libc::ioctl(slave.as_raw_fd(),libc::TIOCSWINSZ,&new_size);libc::kill(child.id() as i32,libc::SIGWINCH);};wait(||requests.lock().unwrap().iter().any(|r|r["tag"]=="terminal.resize"&&r["payload"]["cols"]==120&&r["payload"]["rows"]==40));done_tx.send(true).unwrap();let mut status=None;wait(||{status=child.try_wait().unwrap();status.is_some()});assert!(status.unwrap().success());let mut restored:libc::termios=unsafe{std::mem::zeroed()};unsafe{libc::tcgetattr(slave.as_raw_fd(),&mut restored)};assert_eq!(restored.c_lflag,original.c_lflag);assert_eq!(restored.c_iflag,original.c_iflag);// Reopening attaches to the same server terminal; closing the frontend only interrupts its stream.
 let mut second=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).args(["terminal","fixture","one"]).env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",&config).stdin(Stdio::from(slave.try_clone().unwrap())).stdout(Stdio::from(slave.try_clone().unwrap())).stderr(Stdio::from(slave.try_clone().unwrap())).spawn().unwrap();
 wait(||requests.lock().unwrap().iter().filter(|r|r["tag"]=="terminal.attach").count()==2);thread::sleep(Duration::from_millis(40));unsafe{libc::kill(second.id() as i32,libc::SIGTERM)};let mut status=None;wait(||{status=second.try_wait().unwrap();status.is_some()});assert!(status.unwrap().success());done_tx.send(false).unwrap();unsafe{libc::tcgetattr(slave.as_raw_fd(),&mut restored)};assert_eq!(restored.c_lflag,original.c_lflag);
 // Explicit code action: a private one-use file, a fresh terminal, and exactly one write.
 let directory=root.join("state/omarchy-t3-code/terminal-commands");fs::create_dir_all(&directory).unwrap();fs::set_permissions(&directory,fs::Permissions::from_mode(0o700)).unwrap();let id=uuid::Uuid::new_v4().to_string();let terminal=format!("term-ot3-{id}");let command_file=directory.join(format!("{id}.json"));fs::write(&command_file,json!({"command":"printf fixture","environment":"fixture","thread":"one","terminalId":terminal}).to_string()).unwrap();fs::set_permissions(&command_file,fs::Permissions::from_mode(0o600)).unwrap();received.lock().unwrap().clear();
 let mut third=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).args(["terminal","fixture","one","--run-file"]).arg(&command_file).env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",&config).stdin(Stdio::from(slave.try_clone().unwrap())).stdout(Stdio::from(slave.try_clone().unwrap())).stderr(Stdio::from(slave.try_clone().unwrap())).spawn().unwrap();wait(||received.lock().unwrap().as_str()=="printf fixture\r");assert!(!command_file.exists());assert_eq!(requests.lock().unwrap().iter().filter(|r|r["tag"]=="terminal.write"&&r["payload"]["terminalId"]==terminal).count(),1);done_tx.send(true).unwrap();let mut status=None;wait(||{status=third.try_wait().unwrap();status.is_some()});assert!(status.unwrap().success());
 let replay=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).args(["terminal","fixture","one","--run-file"]).arg(&command_file).env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",&config).output().unwrap();assert!(!replay.status.success());assert!(String::from_utf8_lossy(&replay.stderr).contains("terminal_command_consumed"));
 assert!(!requests.lock().unwrap().iter().any(|r|r["tag"]=="terminal.close"));stop.store(true,Ordering::Relaxed);server.join().unwrap();for t in peers.lock().unwrap().drain(..){t.join().unwrap()}fs::remove_dir_all(root).unwrap();
}
